CREATE FUNCTION public.register_customer(_name text, _organisation text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF; INSERT INTO public.profiles(id,full_name,organisation) VALUES(auth.uid(),left(_name,120),left(_organisation,120)) ON CONFLICT(id) DO NOTHING; INSERT INTO public.user_roles(user_id,role) VALUES(auth.uid(),'customer') ON CONFLICT DO NOTHING; END $$;
GRANT EXECUTE ON FUNCTION public.register_customer(text,text) TO authenticated;
REVOKE UPDATE ON public.lc_applications FROM authenticated;
REVOKE UPDATE ON public.approvals FROM authenticated;
REVOKE UPDATE ON public.discrepancies FROM authenticated;
REVOKE UPDATE ON public.clarifications FROM authenticated;
CREATE FUNCTION public.decide_discrepancy(_id uuid,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _app uuid; BEGIN IF NOT public.has_role(auth.uid(),'officer') AND NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Officer role required'; END IF; IF length(trim(_reason))<3 THEN RAISE EXCEPTION 'A decision reason is required'; END IF; UPDATE public.discrepancies SET status='Resolved',resolution_reason=_reason,resolved_by=auth.uid() WHERE id=_id AND status='Open' RETURNING application_id INTO _app; IF _app IS NULL THEN RAISE EXCEPTION 'Open discrepancy not found'; END IF; INSERT INTO public.audit_logs(application_id,actor_id,action,details) VALUES(_app,auth.uid(),'Discrepancy resolved',_reason); END $$;
GRANT EXECUTE ON FUNCTION public.decide_discrepancy(uuid,text) TO authenticated;
CREATE FUNCTION public.respond_clarification(_id uuid,_response text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _app uuid; BEGIN IF length(trim(_response))<2 THEN RAISE EXCEPTION 'Response required'; END IF; UPDATE public.clarifications c SET response=_response,status='Responded',responded_by=auth.uid() FROM public.lc_applications a WHERE c.id=_id AND c.application_id=a.id AND a.customer_id=auth.uid() AND c.status='Awaiting customer' RETURNING c.application_id INTO _app; IF _app IS NULL THEN RAISE EXCEPTION 'Clarification not found'; END IF; INSERT INTO public.audit_logs(application_id,actor_id,action,details) VALUES(_app,auth.uid(),'Clarification answered',_response); END $$;
GRANT EXECUTE ON FUNCTION public.respond_clarification(uuid,text) TO authenticated;
CREATE FUNCTION public.request_approval(_app uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'officer') THEN RAISE EXCEPTION 'Officer role required'; END IF; IF EXISTS(SELECT 1 FROM public.discrepancies WHERE application_id=_app AND status<>'Resolved') OR EXISTS(SELECT 1 FROM public.clarifications WHERE application_id=_app AND status<>'Responded') THEN RAISE EXCEPTION 'Resolve discrepancies and clarifications first'; END IF; IF NOT EXISTS(SELECT 1 FROM public.lc_documents WHERE application_id=_app) THEN RAISE EXCEPTION 'Upload and review documents first'; END IF; IF NOT EXISTS(SELECT 1 FROM public.extracted_fields WHERE application_id=_app) OR EXISTS(SELECT 1 FROM public.extracted_fields WHERE application_id=_app AND confidence<80 AND reviewed_by IS NULL) THEN RAISE EXCEPTION 'Complete extraction and low-confidence review first'; END IF; IF EXISTS(SELECT 1 FROM public.approvals WHERE application_id=_app AND decision='Pending') THEN RAISE EXCEPTION 'Approval already requested'; END IF; INSERT INTO public.approvals(application_id) VALUES(_app); UPDATE public.lc_applications SET stage='LC issuance',status='Approval required',updated_at=now() WHERE id=_app; INSERT INTO public.audit_logs(application_id,actor_id,action) VALUES(_app,auth.uid(),'Approval requested'); END $$;
GRANT EXECUTE ON FUNCTION public.request_approval(uuid) TO authenticated;
CREATE FUNCTION public.decide_approval(_id uuid,_decision text,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _app uuid; BEGIN IF NOT public.has_role(auth.uid(),'approver') AND NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Approver role required'; END IF; IF _decision NOT IN ('Approved','Rejected') OR length(trim(_reason))<3 THEN RAISE EXCEPTION 'A valid decision and reason are required'; END IF; SELECT application_id INTO _app FROM public.approvals WHERE id=_id AND decision='Pending'; IF _app IS NULL THEN RAISE EXCEPTION 'Pending approval not found'; END IF; IF _decision='Approved' AND (NOT EXISTS(SELECT 1 FROM public.lc_documents WHERE application_id=_app) OR NOT EXISTS(SELECT 1 FROM public.extracted_fields WHERE application_id=_app) OR EXISTS(SELECT 1 FROM public.extracted_fields WHERE application_id=_app AND confidence<80 AND reviewed_by IS NULL) OR EXISTS(SELECT 1 FROM public.discrepancies WHERE application_id=_app AND status<>'Resolved') OR EXISTS(SELECT 1 FROM public.clarifications WHERE application_id=_app AND status<>'Responded')) THEN RAISE EXCEPTION 'Approval blocked: outstanding documents, extraction review, discrepancies or clarifications'; END IF; UPDATE public.approvals SET decision=_decision,reason=_reason,decided_by=auth.uid(),decided_at=now() WHERE id=_id; UPDATE public.lc_applications SET status=CASE WHEN _decision='Approved' THEN 'Issued' ELSE 'Rejected' END,stage='LC issuance',updated_at=now() WHERE id=_app; INSERT INTO public.audit_logs(application_id,actor_id,action,details) VALUES(_app,auth.uid(),_decision,_reason); END $$;
GRANT EXECUTE ON FUNCTION public.decide_approval(uuid,text,text) TO authenticated;
CREATE FUNCTION public.mark_extraction_reviewed(_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _app uuid; BEGIN IF NOT public.has_role(auth.uid(),'officer') THEN RAISE EXCEPTION 'Officer role required'; END IF; UPDATE public.extracted_fields SET reviewed_by=auth.uid() WHERE id=_id AND reviewed_by IS NULL RETURNING application_id INTO _app; IF _app IS NULL THEN RAISE EXCEPTION 'Field not found or already reviewed'; END IF; INSERT INTO public.audit_logs(application_id,actor_id,action) VALUES(_app,auth.uid(),'Extraction field reviewed'); END $$;
GRANT EXECUTE ON FUNCTION public.mark_extraction_reviewed(uuid) TO authenticated;